.form-page{position:relative;width:612pt;height:792pt;overflow:hidden;background:#fff;}
.form-page + .form-page{page-break-before:always;}
@page gdflow{margin:54pt 0 72pt 0;}
.gd-flow{page:gdflow;padding:0 54pt 0 54pt;}
@page gdrun{margin:0pt 0 0pt 0;}
.gd-flow.gd-run{page:gdrun;}
.gd-doc table.gd-runt{width:100%;border-collapse:collapse;table-layout:fixed;}
.gd-doc table.gd-runt>*>tr>td{padding:0;}
